@Component("salesCampaign-subscriber")
public class SalesCampaignSubscriber extends BaseSubscriber {

	public SalesCampaignSubscriber() {
	}
	
    public SubscriptionQueryResult<List<SalesCampaign>, SalesCampaign> salesCampaignSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllSalesCampaignQuery(), 
                		ResponseTypes.multipleInstancesOf(SalesCampaign.class),
                		ResponseTypes.instanceOf(SalesCampaign.class));
    }

    public SubscriptionQueryResult<SalesCampaign, SalesCampaign> salesCampaignSubscribe(@DestinationVariable UUID salesCampaignId) {
        return queryGateway
                .subscriptionQuery(new FindSalesCampaignQuery(new LoadSalesCampaignFilter(salesCampaignId)), 
                		ResponseTypes.instanceOf(SalesCampaign.class),
                		ResponseTypes.instanceOf(SalesCampaign.class));
    }





}

